# Strengthen wire script for L2/L4
wire = r"""
/* LAYER L2 L4 FORCE WIRE */
(function(){
  function bind(){
    document.querySelectorAll('[data-view="L2"]').forEach(function(b){
      b.onclick = function(e){ e.preventDefault(); e.stopPropagation(); openLyr('lyrOverlay2'); return false; };
    });
    document.querySelectorAll('[data-view="L4"]').forEach(function(b){
      b.onclick = function(e){ e.preventDefault(); e.stopPropagation(); openLyr('lyrOverlay4'); return false; };
    });
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', bind);
  else bind();
  setTimeout(bind, 400);
  setTimeout(bind, 1200);
  try {
    if(typeof layerViews !== 'undefined'){
      layerViews.L2 = function(){ openLyr('lyrOverlay2'); return '<div class="card"><p>Layer 2 open</p></div>'; };
      layerViews.L4 = function(){ openLyr('lyrOverlay4'); return '<div class="card"><p>Layer 4 open</p></div>'; };
    }
  } catch(e){}
})();
"""
t = re.sub(r"/\* LAYER L2 L4 FORCE WIRE \*/[\s\S]*?\}\)\(\);\s*", "", t)
